from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
import re

wb = load_workbook('/root/data/workbook.xlsx', data_only=False)
ws = wb['Data']

years = {2019,2020,2021,2022,2023}
found = []
for r in range(1, ws.max_row+1):
    for c in range(1, ws.max_column+1):
        v = ws.cell(row=r, column=c).value
        if isinstance(v,(int,float)) and int(v) in years:
            found.append((r,c,v))
        elif isinstance(v,str) and re.fullmatch(r'20(19|20|21|22|23)', v.strip()):
            found.append((r,c,v.strip()))

print('Data max_row', ws.max_row, 'max_col', ws.max_column)
print('Year-like cells found:', len(found))
for (r,c,v) in found[:50]:
    print(f'Data!{get_column_letter(c)}{r}={v!r}')

# Print rows 1-25 cols A-L for context
print('\n=== Data rows 1-25 cols A-L ===')
for r in range(1, 26):
    vals=[]
    for c in range(1, 13):
        v=ws.cell(row=r,column=c).value
        vals.append('' if v is None else str(v))
    while vals and vals[-1]=='':
        vals.pop()
    print(f'{r}:\t' + ' | '.join(vals))
